cd /tmp/sv-7aeed7ce163b409f8545c86952cefe04/advanced-multi-complexity && dotnet list package --format json 2>/dev/null | python3 -c "import sys,json; print(json.dumps(json.load(sys.stdin),indent=2))" > after-cpm-packages.json && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: project -> framework -> package -> version
def build_lookup(data):
    lookup = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        lookup[name] = {}
        for fw in proj['frameworks']:
            lookup[name][fw['framework']] = {p['id']: p['resolvedVersion'] for p in fw['topLevelPackages']}
    return lookup

b = build_lookup(baseline)
a = build_lookup(after)

changes = []
unchanged = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for fw in sorted(set(list(b.get(proj,{}).keys()) + list(a.get(proj,{}).keys()))):
        bp = b.get(proj,{}).get(fw,{})
        ap = a.get(proj,{}).get(fw,{})
        for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
            bv = bp.get(pkg, 'N/A')
            av = ap.get(pkg, 'N/A')
            if bv != av:
                changes.append(f'{proj} ({fw}): {pkg} {bv} -> {av}')
            else:
                unchanged.append(f'{proj} ({fw}): {pkg} = {av}')

print('=== CHANGES ===')
for c in changes:
    print(c)
if not changes:
    print('(none)')
print()
print(f'=== UNCHANGED: {len(unchanged)} packages ===')
for u in unchanged:
    print(u)
"

